def show(label, fn):
    try:
        r = fn()
    except Exception as e:
        r = type(e).__name__
    print(f"{label} -> {r!r}")


for s in ["42", "\u0664\u0662", "\u00b2", "4.0", " 7 ", "1_000"]:
    show(f"int({s!r})", lambda: int(s))
    show(f"{s!r}.isdigit()", lambda: s.isdigit())

